signed int __cdecl Q_GetMaxTaxRate_sub_40BD10(int aCivIndex)
{
  if ( Civs[aCivIndex].Government <= CIV2_GOVERNMENT_DESPOTISM )
  {
    return 6;                                   // Anarchy, Despotism
  }
  if ( Civs[aCivIndex].Government == CIV2_GOVERNMENT_MONARCHY )
  {
    return 7;                                   // Monarchy
  }
  if ( Civs[aCivIndex].Government > CIV2_GOVERNMENT_REPUBLIC )
  {
    return 10;                                  // Democracy
  }
  return 8;                                     // Communism, Fundamentalism, Republic
}

//----- (0040BDAC) --------------------------------------------------------
void __cdecl Q_NormalizeRates_sub_40BDAC(_DWORD *aTax, _DWORD *aScience, _DWORD *aLuxury, _DWORD *a4, _DWORD *a5, _DWORD *a6)
{
  int MaxRate; // [esp+Ch] [ebp-4h]

  MaxRate = V_CurrentTaxWindow_dword_63CBB4->MaxRate;
  while ( *aTax + *aScience + *aLuxury < 0xA )
  {
    if ( *aScience >= MaxRate || *a4 <= *aScience || *a5 )
    {
      if ( *aLuxury >= MaxRate || *a6 )
      {
        if ( *aScience >= MaxRate || *a5 )
        {
          ++*aTax;
        }
        else
        {
          ++*aScience;
        }
      }
      else
      {
        ++*aLuxury;
      }
    }
    else
    {
      ++*aScience;
    }
  }
  while ( *aTax + *aScience + *aLuxury > 0xA )
  {
    if ( !*aScience || *a5 )
    {
      if ( !*aLuxury || *a6 )
      {
        --*aTax;
      }
      else
      {
        --*aLuxury;
      }
    }
    else
    {
      --*aScience;
    }
  }
}

