// Process civilization prerequisite chains to flatten technology dependency trees
// This optimizes technology requirement checking by collapsing multi-level dependencies
void __cdecl Q_FlattenTechnologyPrerequisites_sub_415952()
{
  int currentPreq; // [esp+Ch] [ebp-10h]
  int i; // [esp+10h] [ebp-Ch]
  int preqSlot; // [esp+14h] [ebp-8h]
  MACRO_BOOL foundValidPreq; // [esp+18h] [ebp-4h]

  Game.EnabledTechnologyCount = 0;
  for ( i = 0; i < 100; ++i )
  {
    if ( g_RulesCivilizes[i].IsEnabled )
    {
      ++Game.EnabledTechnologyCount;
      for ( preqSlot = 0; preqSlot < 2; ++preqSlot )
      {
        currentPreq = g_RulesCivilizes[i].Preq[preqSlot];
        foundValidPreq = FALSE;
        // Follow the prerequisite chain until we find a valid enabled technology or reach the end of the chain
        while ( currentPreq >= 0 && foundValidPreq == FALSE )
        {
          // Check if this prerequisite technology is itself enabled
          if ( g_RulesCivilizes[currentPreq].IsEnabled )
          {
            foundValidPreq = TRUE;
          }
          else
          {
            // Prerequisite is disabled, follow its first prerequisite instead
            // This collapses chains like: TechA -> TechB(disabled) -> TechC
            // Result: TechA -> TechC directly
            currentPreq = g_RulesCivilizes[currentPreq].Preq[0];
          }
        }
        // Update the prerequisite to point directly to the valid enabled technology
        // If no valid prerequisite found, currentPreq will be -1 or point to disabled tech
        g_RulesCivilizes[i].Preq[preqSlot] = currentPreq;
      }
    }
  }
}

