void __cdecl Q_RemoveTradeRoute_sub_440325(int aCityIndex, int aRouteIndex)
{
  while ( Cities[aCityIndex].TradeRoutes - 1 > aRouteIndex )
  {
    Cities[aCityIndex].TradePartner[aRouteIndex] = Cities[aCityIndex].TradePartner[aRouteIndex + 1];
    Cities[aCityIndex].TradeCommodity[aRouteIndex] = Cities[aCityIndex].TradeCommodity[aRouteIndex + 1];
    ++aRouteIndex;
  }
  --Cities[aCityIndex].TradeRoutes;
  Cities[aCityIndex].CityAttributes |= CIV2_CITY_ATTR_UPDATE_SUPPLY_DEMAND;
}

