//----- (0045A8E3) --------------------------------------------------------
// Triggers defensive pacts and cascades war declarations across an alliance network.
// When an attacker hits a victim, all of the victim's allies are forced to declare war on the attacker.
// Includes support for multiplayer network packet synchronization.
void __cdecl Q_TriggerAllianceWar_sub_45A8E3(int VictimCivIndex, int AttackerCivIndex)
{
  char *text; // eax MAPDST
  int allyCivIndex; // [esp+Ch] [ebp-4h]

  if ( (Civs[VictimCivIndex].Treaties[AttackerCivIndex] & CIV2_TREATY_CONTACT) != 0 )
  {
    for ( allyCivIndex = 1; allyCivIndex < 8; ++allyCivIndex )
    {
      // Find a third-party nation that is allied with the victim, not already at war/allied
      // with the attacker, and has discovered/met the attacker on the map.
      if ( allyCivIndex != VictimCivIndex
        && allyCivIndex != AttackerCivIndex
        && (Civs[VictimCivIndex].Treaties[allyCivIndex] & CIV2_TREATY_ALLIANCE) != 0
        && (Civs[allyCivIndex].Treaties[AttackerCivIndex] & (CIV2_TREATY_WAR|CIV2_TREATY_ALLIANCE)) == 0
        && (Civs[allyCivIndex].Treaties[AttackerCivIndex] & CIV2_TREATY_CONTACT) != 0 )
      {
        text = j_Q_GetStringNationPlural_sub_493C7D(VictimCivIndex);
        j_Q_DlgParams_SetStringText_sub_40FF60(1, text);
        text = j_Q_GetStringNationPlural_sub_493C7D(allyCivIndex);
        j_Q_DlgParams_SetStringText_sub_40FF60(2, text);
        text = j_Q_GetStringNationPlural_sub_493C7D(AttackerCivIndex);
        j_Q_DlgParams_SetStringText_sub_40FF60(3, text);
        // CASE 1: The Attacker is a Human Player
        if ( (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) != 0 )
        {
          // If the Victim is an AI (prevents human-to-human local UI conflicts)
          if ( (Game.ActiveHumanPlayers & (1 << VictimCivIndex)) == 0 )
          {
            // Local human display: You attacked an AI, and its ally honors the pact
            if ( g_LocalHumanCivIndex == AttackerCivIndex )
            {
              // @title=Foreign Minister
              // %STRING1 activate their alliance with the
              // %STRING2.  %STRING2 declare war on %STRING3!
              j_Q_PopupSimpleGAMEWithSprite_sub_410030(
                "ACTIVATEALLY",
                (T_Sprite *)((char *)&stru_648018
                           + (((char *)&stru_63FC98 - (char *)&stru_648018) & ((Game.TechsDiscovered[CIV2_TECH_COMMUNISM] != 0) - 1))),
                0);
            }
            else if ( Game.MultiType >= 3u )
            {
              j_Q_NetSendDialogCommand_sub_511880(0x38, gNetMgr.Net54[gNetMgr.Net54Idx[AttackerCivIndex]].Unknown_0, 4, 0, 0, 0);
            }
          }
          // Establish official war state between the ally and the attacker
          j_Q_ChangeAttitude_sub_456F20(allyCivIndex, AttackerCivIndex, 100);
          j_Q_SetTreaties_sub_467825(allyCivIndex, AttackerCivIndex, CIV2_TREATY_WAR|CIV2_TREATY__COALITION_WAR|CIV2_TREATY_CONTACT);
          Civs[allyCivIndex].Treaties[AttackerCivIndex] |= CIV2_TREATY__THEATER_WAR_ACTIVE|CIV2_TREATY__CASUS_BELLI;
          Civs[VictimCivIndex].Treaties[AttackerCivIndex] |= CIV2_TREATY__THEATER_WAR_ACTIVE|CIV2_TREATY__CASUS_BELLI;
          Civs[AttackerCivIndex].LastContactTurn[allyCivIndex] = Game.Turn;
        }
        // CASE 2: The Victim is the Human Player (An AI backstabbed the human, so human's AI ally joins to help)
        else if ( (Game.ActiveHumanPlayers & (1 << VictimCivIndex)) != 0 )
        {
          // If the Attacker is an AI
          if ( (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) == 0 )
          {
            // Local human display: An AI attacked you, and your AI ally steps up to protect you
            if ( g_LocalHumanCivIndex == VictimCivIndex )
            {
              // @title=Foreign Minister
              // The %STRING2 have announced that they will
              // come to our aid by declaring war on the
              // %STRING3!
              j_Q_PopupSimpleGAMEWithSprite_sub_410030(
                "ALLYHELPS",
                (T_Sprite *)((char *)&stru_648018
                           + (((char *)&stru_63FC98 - (char *)&stru_648018) & ((Game.TechsDiscovered[CIV2_TECH_COMMUNISM] != 0) - 1))),
                0);
            }
            else if ( Game.MultiType >= 3u )
            {
              j_Q_NetSendDialogCommand_sub_511880(0x39, gNetMgr.Net54[gNetMgr.Net54Idx[VictimCivIndex]].Unknown_0, 4, 0, 0, 0);
            }
          }
          // Establish official war state between your helpful ally and the AI attacker
          j_Q_SetTreaties_sub_467825(allyCivIndex, AttackerCivIndex, CIV2_TREATY_WAR|CIV2_TREATY__COALITION_WAR|CIV2_TREATY_CONTACT);
          Civs[allyCivIndex].Treaties[AttackerCivIndex] |= CIV2_TREATY__THEATER_WAR_ACTIVE|CIV2_TREATY__CASUS_BELLI;
        }
      }
    }
  }
}

//----- (0045AC71) --------------------------------------------------------
// Applies reputation penalties and updates diplomatic states when a civilization declares war.
// Handles betrayals of alliances, broken peace treaties, and adjustments to third-party attitudes.
//   AttackerCivIndex  The index of the nation declaring war.
//   VictimCivIndex    The index of the nation being attacked.
//   RequesterCivIndex The index of the AI ally who requested this intervention.
//                     Passes -1 if the war is declared independently without a request.
void __cdecl Q_ApplyWarDeclarationPenalty_sub_45AC71(int AttackerCivIndex, int VictimCivIndex, int RequesterCivIndex)
{
  // If this war was requested by an ally, that ally becomes grateful to the attacker
  if ( RequesterCivIndex >= 0 )
  {
    ++Civs[RequesterCivIndex].Reputation2[AttackerCivIndex];
  }
  // CASE 1: The attacker is BETRAYING an active Alliance with the victim
  if ( (Civs[AttackerCivIndex].Treaties[VictimCivIndex] & CIV2_TREATY_ALLIANCE) != 0 )
  {
    // Penalty A: General reputation worsens on higher difficulties unless protected by the Eiffel Tower
    if ( Game.DifficultyLevel )
    {
      if ( !j_Q_CivHasWonder_sub_453E51(AttackerCivIndex, CIV2_WONDER_EIFFEL_TOWER) )
      {
        ++Civs[AttackerCivIndex].Reputation;
      }
    }
    // Penalty B: Additional penalties if attacking independently (backstabbing without an ally's plea)
    if ( RequesterCivIndex < 0 )
    {
      // Severe double reputation degradation
      ++Civs[AttackerCivIndex].Reputation;
      if ( (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) != 0 )
      {
        // Victim harbors deep localized resentment
        --Civs[AttackerCivIndex].Reputation2[VictimCivIndex];
      }
    }
    // Reward: If an ally requested this, the ally's diplomatic attitude toward the attacker improves (25 points better)
    if ( RequesterCivIndex >= 0 )
    {
      j_Q_ChangeAttitude_sub_456F20(RequesterCivIndex, AttackerCivIndex, -25);
    }
    // Break the formal alliance structure between them
    j_Q_CancelAlliance_sub_467EF2(AttackerCivIndex, VictimCivIndex);
    // If a human is the betrayer, the AI victim marks them for a blood feud/vendetta
    if ( (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) != 0 )
    {
      Civs[VictimCivIndex].Treaties[AttackerCivIndex] |= CIV2_TREATY_VENDETTA;
    }
  }
  else                                          // CASE 2: The attacker is NOT allied, but breaking an existing Peace or Ceasefire agreement
  {
    if ( (Civs[AttackerCivIndex].Treaties[VictimCivIndex] & (CIV2_TREATY_PEACE|CIV2_TREATY_CEASE_FIRE)) != 0 )
    {
      // Sub-case: Breaking a full signed Peace Treaty AND Ceasefire concurrently (severe treaty breach)
      if ( (Civs[AttackerCivIndex].Treaties[VictimCivIndex] & CIV2_TREATY_PEACE) != 0
        && (Civs[AttackerCivIndex].Treaties[VictimCivIndex] & CIV2_TREATY_CEASE_FIRE) != 0 )
      {
        // Hyper-power penalty: If a massive empire (Rating 7, >4 cities) breaks peace unprovoked, its global reputation suffers
        if ( Game.CivPowerRating[AttackerCivIndex] == 7 && Civs[AttackerCivIndex].Cities > 4 && RequesterCivIndex < 0 )
        {
          ++Civs[AttackerCivIndex].Reputation;
        }
        if ( Game.DifficultyLevel )
        {
          if ( !j_Q_CivHasWonder_sub_453E51(AttackerCivIndex, CIV2_WONDER_EIFFEL_TOWER) )
          {
            ++Civs[AttackerCivIndex].Reputation;
          }
        }
        if ( RequesterCivIndex < 0 && (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) != 0 )
        {
          --Civs[AttackerCivIndex].Reputation2[VictimCivIndex];
        }
      }
      // Standard Peace/Ceasefire breach penalties (replicated logic for single treaty violations)
      if ( Game.CivPowerRating[AttackerCivIndex] == 7 && Civs[AttackerCivIndex].Cities > 4 && RequesterCivIndex < 0 )
      {
        ++Civs[AttackerCivIndex].Reputation;
      }
      if ( Game.DifficultyLevel )
      {
        if ( !j_Q_CivHasWonder_sub_453E51(AttackerCivIndex, CIV2_WONDER_EIFFEL_TOWER) )
        {
          ++Civs[AttackerCivIndex].Reputation;
        }
      }
      if ( RequesterCivIndex < 0 && (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) != 0 )
      {
        --Civs[AttackerCivIndex].Reputation2[VictimCivIndex];
      }
      // If an ally requested this peace-breach, the ally approves of the action (15 points better attitude)
      if ( RequesterCivIndex >= 0 )
      {
        j_Q_ChangeAttitude_sub_456F20(RequesterCivIndex, AttackerCivIndex, -15);
      }
    }
    // CASE 3: Declaring war from a neutral state (no active treaties broken)
    else if ( RequesterCivIndex >= 0 )
    {
      // Ally slightly approves of you attacking their enemy from a neutral stance (5 points better attitude)
      j_Q_ChangeAttitude_sub_456F20(RequesterCivIndex, AttackerCivIndex, -5);
    }
    // Set Vendetta flag if a human attacks an AI
    if ( (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) != 0 )
    {
      Civs[VictimCivIndex].Treaties[AttackerCivIndex] |= CIV2_TREATY_VENDETTA;
    }
    j_Q_SetTreaties_sub_467825(AttackerCivIndex, VictimCivIndex, CIV2_TREATY_WAR);
    // Human-specific escalation rules (Casus Belli processing & Alliance cascading)
    if ( (Game.ActiveHumanPlayers & (1 << AttackerCivIndex)) != 0 )
    {
      Civs[AttackerCivIndex].Treaties[VictimCivIndex] |= CIV2_TREATY__THEATER_WAR_ACTIVE|CIV2_TREATY__CASUS_BELLI;
      Civs[AttackerCivIndex].LastContactTurn[VictimCivIndex] = Game.Turn;
      // Triggers defensive pacts: Forces the victim's allies to also declare war on the human attacker
      j_Q_TriggerAllianceWar_sub_45A8E3(VictimCivIndex, AttackerCivIndex);
    }
  }
}

//----- (0045B0D6) --------------------------------------------------------
// Demands that the human player honors their alliance and helps CivIndex1 in their war against CivIndex2.
// If the human refuses, the AI may offer a gold bribe based on its local military desperation.
// Continued refusal results in breaking the alliance or heavy diplomatic penalties.
void __cdecl Q_AiDemandHelpFromHumanAlly_sub_45B0D6(int CivIndex, int AttackerCivIndex)
{
  char *attackerNamePlural; // eax
  int choice; // [esp+Ch] [ebp-14h]
  int goldBribeAmount; // [esp+10h] [ebp-10h]
  int desperatenessScore; // [esp+14h] [ebp-Ch]
  int m; // [esp+18h] [ebp-8h]
  int humanCivIndex; // [esp+1Ch] [ebp-4h]

  humanCivIndex = g_LocalHumanCivIndex;
  if ( (Game.ActiveHumanPlayers & (1 << g_LocalHumanCivIndex)) != 0
    && (Civs[CivIndex].Treaties[g_LocalHumanCivIndex] & CIV2_TREATY_ALLIANCE) != 0
    && (Civs[g_LocalHumanCivIndex].Treaties[AttackerCivIndex] & (CIV2_TREATY_WAR|CIV2_TREATY_ALLIANCE)) == 0 )
  {
    if ( j_Q_DemandAudience_sub_458DF9(g_LocalHumanCivIndex, CivIndex, -1, -1) )
    {
      attackerNamePlural = j_Q_GetStringNationPlural_sub_493C7D(AttackerCivIndex);
      j_Q_DlgParams_SetStringText_sub_40FF60(1, attackerNamePlural);
      // @title=%STRING0 Emissary
      // "We have been attacked by the evil %STRING1!
      // Under the terms of our alliance, we insist that you
      // come to our aid at once!"
      choice = j_Q_PopupSimpleGAMEWithSprite_sub_410030(
                 "DEMANDHELP",
                 (T_Sprite *)((char *)&stru_648018
                            + (((char *)&stru_63FC98 - (char *)&stru_648018) & ((Game.TechsDiscovered[CIV2_TECH_COMMUNISM] != 0) - 1))),
                 0);
      if ( choice != 1 )
      {
        desperatenessScore = 0;
        for ( m = 1; m < 63; ++m )
        {
          // If the AI has cities here, but its local garrisons are outnumbered by the attacker's offensive power
          if ( Civs[CivIndex].CityCountPerLandMass[m] > (Civs[CivIndex].Cities > 1)
            && Civs[CivIndex].MilitaryUnitsPerLandMass[m] < (int)Civs[AttackerCivIndex].AttSumPerLandMass[m] )
          {
            // Calculate a desperation rating scaled by game difficulty (higher multiplier on easy difficulties)
            desperatenessScore += (Game.DifficultyLevel == 0 ? 4 : 2)
                                * Civs[AttackerCivIndex].AttSumPerLandMass[m]
                                / (Civs[CivIndex].MilitaryUnitsPerLandMass[m] + 1);
          }
        }
        if ( desperatenessScore )
        {
          goldBribeAmount = 50 * j_Q_Clamp_sub_5ADFA0(desperatenessScore, 0, Civs[CivIndex].Gold / 50);
          if ( goldBribeAmount )
          {
            j_Q_DlgParams_SetNumber_sub_421DA0(0, goldBribeAmount);
            // @title=%STRING0 Emissary
            // "Perhaps we could throw in %NUMBER0 gold to
            // make it worth your while?"
            choice = j_Q_PopupSimpleGAMEWithSprite_sub_410030(
                       "HELPBONUS",
                       (T_Sprite *)((char *)&stru_648018
                                  + (((char *)&stru_63FC98 - (char *)&stru_648018) & ((Game.TechsDiscovered[CIV2_TECH_COMMUNISM] != 0) - 1))),
                       0);
            if ( choice == 1 )
            {
              Civs[CivIndex].Gold -= goldBribeAmount;
              Civs[humanCivIndex].Gold += goldBribeAmount;
              j_Q_DrawSideBar_sub_569363(TRUE);
            }
          }
        }
      }
      if ( choice == 1 )
      {
        j_Q_ApplyWarDeclarationPenalty_sub_45AC71(humanCivIndex, AttackerCivIndex, CivIndex);
EXIT:
        j_sub_45918E();
        return;
      }
      // @title=%STRING0 Emissary
      // "Very well, but do not come crying to us for
      // help in the future."
      j_Q_PopupSimpleGAMEWithSprite_sub_410030(
        "DIDNTHELP",
        (T_Sprite *)((char *)&stru_648018 + (((char *)&stru_63FC98 - (char *)&stru_648018) & ((Game.TechsDiscovered[CIV2_TECH_COMMUNISM] != 0) - 1))),
        0);
      // Betrayal penalty: If our base alliance alignment was already rocky (g_Attitude > 50), break it completely
      if ( g_Attitude > 50 )
      {
        j_Q_CancelAlliance_sub_467EF2(humanCivIndex, CivIndex);
        goto EXIT;
      }
    }
    // If refused to speak, or if alliance didn't snap, heavily degrade the AI's internal attitude toward the human
    j_Q_ChangeAttitude_sub_456F20(CivIndex, humanCivIndex, 100);
    goto EXIT;
  }
}

