// Converts the game turn into a calendar year
int __cdecl Q_ConvertTurnToYear_sub_484FEC(int Turn)
{
  int turnsAfterLaunch; // eax
  int TurnYearIncrement; // [esp+Ch] [ebp-18h]
  int spaceshipYearsBonus; // [esp+10h] [ebp-14h]
  int era; // [esp+14h] [ebp-10h]
  int calculatedYear; // [esp+18h] [ebp-Ch]
  int difficultyIndex; // [esp+1Ch] [ebp-8h]
  int scale; // [esp+20h] [ebp-4h]

  spaceshipYearsBonus = 0;
  difficultyIndex = Game.DifficultyLevel;
  // Adjust difficulty index based on map size
  if ( (Game.MapFlags & CIV2_MAP_FLAG_AREA_BIG) != 0 )
  {
    difficultyIndex = Game.DifficultyLevel - 1;
  }
  if ( (Game.MapFlags & CIV2_MAP_FLAG_AREA_SMALL) != 0 )
  {
    ++difficultyIndex;
  }
  // Select the time-scale set (0-3) based on adjusted difficulty
  scale = j_Q_Clamp_sub_5ADFA0(difficultyIndex - 1, 0, 3);
  // Spaceship Launch Logic:
  // Once a ship is launched, calendar progression locks to 1 year per turn.
  if ( Game._FirstSpaceShipLaunchTurn >= 0 )
  {
    turnsAfterLaunch = Turn - Game._FirstSpaceShipLaunchTurn;
    if ( turnsAfterLaunch <= 0 )
    {
      turnsAfterLaunch = 0;
    }
    // Each turn after launch counts as exactly 1 year
    spaceshipYearsBonus = turnsAfterLaunch;
    // Subtract these turns to "freeze" normal progression
    Turn -= turnsAfterLaunch;
  }
  if ( (Game.MapFlags & CIV2_MAP_FLAG_SCENARIO_STARTED) != 0 && ScenarioParameters.TurnYearIncrement && ScenarioParameters.StartingYear )
  {
    // Scenario-specific calendar override
    if ( ScenarioParameters.TurnYearIncrement <= 0 )
    {
      TurnYearIncrement = -ScenarioParameters.TurnYearIncrement;
    }
    else
    {
      TurnYearIncrement = ScenarioParameters.TurnYearIncrement;
    }
    // Year = Bonus + (Step * Remaining Turns) + StartYear - 1
    return spaceshipYearsBonus + TurnYearIncrement * Turn + ScenarioParameters.StartingYear - 1;
  }
  else
  {
    // Standard game calendar using era-based time scales
    if ( Turn )
    {
      --Turn;
    }
    // Find which era the current turn belongs to
    for ( era = 0; TimeScaleTable[scale][era].TurnsInEra < Turn && era < 6; ++era )
    {
      Turn -= TimeScaleTable[scale][era].TurnsInEra;
    }
    if ( era >= 6 )
    {
      // Exceeding the 6th era: each turn beyond the table counts as 1 year
      calculatedYear = Turn + TimeScaleTable[scale][5].BaseYear + TimeScaleTable[scale][5].TurnsInEra * TimeScaleTable[scale][5].YearsPerTurn;
    }
    else
    {
      // Calculate year within the identified era
      calculatedYear = TimeScaleTable[scale][era].BaseYear + Turn * TimeScaleTable[scale][era].YearsPerTurn;
    }
    // Adjust for the lack of "Year 0" in historical calendars
    if ( !calculatedYear )
    {
      calculatedYear = 1;
    }
    return spaceshipYearsBonus + calculatedYear;
  }
}

