//----- (0055BEF9) --------------------------------------------------------
BOOL __cdecl Q_IsOverruledBySenate_sub_55BEF9(int CivIndex1, int CivIndex2)
{
  int a1; // [esp+Ch] [ebp-4h]

  if ( Civs[CivIndex1].Government < CIV2_GOVERNMENT_REPUBLIC )
  {
    return 0;
  }
  if ( (Game.MapFlags & CIV2_MAP_FLAG_SCENARIO_STARTED) != 0 && (ScenarioParameters.Flags & CIV2_SCN_FLAG_TOTAL_WAR) != 0 )
  {
    return 0;
  }
  a1 = 0;
  if ( (Civs[CivIndex2].Treaties[CivIndex1] & CIV2_TREATY_0x1000) != 0 )
  {
    a1 = 25;
  }
  if ( j_Q_CivHasWonder_sub_453E51(CivIndex1, CIV2_WONDER_UNITED_NATIONS) )
  {
    a1 = 50;
  }
  if ( (unsigned __int8)Civs[CivIndex1].SenateChances < j_Q_Clamp_sub_5ADFA0(15 * Civs[CivIndex2].Reputation + a1, 0, 75) )
  {
    return 0;
  }
  if ( Civs[CivIndex1].Government < CIV2_GOVERNMENT_DEMOCRACY )
  {
    return (Civs[CivIndex1].CivFlags & CIV2_CIV_FLAG_SENATE_VETO) != 0;
  }
  return 1;
}

//----- (0055C066) --------------------------------------------------------
void __cdecl Q_SetGovernment_sub_55C066(int CivIndex, MACRO_CIV2_GOVERNMENT Government)
{
  int oldGovernment; // [esp+Ch] [ebp-Ch]
  int j; // [esp+10h] [ebp-8h]
  int i; // [esp+14h] [ebp-4h]

  oldGovernment = Civs[CivIndex].Government;
  Civs[CivIndex].Government = Government;
  if ( (unsigned __int8)Civs[CivIndex].Government != oldGovernment )
  {
    // If transitioning to Anarchy or if this is an AI civilization, clear Vendettas
    if ( Civs[CivIndex].Government == CIV2_GOVERNMENT_ANARCHY || (Game.ActiveHumanPlayers & (1 << CivIndex)) == 0 )
    {
      // Cancel "Vendetta" treaties/states other civs held against this civilization
      for ( i = 0; i < 8; ++i )
      {
        Civs[i].Treaties[CivIndex] &= ~CIV2_TREATY_VENDETTA;
      }
    }
    if ( (Game.ActiveHumanPlayers & (1 << CivIndex)) != 0 )
    {
      Game.word_655AEE &= ~4u;
      for ( j = 0; Game.TotalCities > j; ++j )
      {
        if ( Cities[j].ID )
        {
          if ( Cities[j].Owner == CivIndex )
          {
            j_Q_CalcCityGlobals_sub_4EB4ED(j, 1);
            if ( Cities[j].Building == CIV2_TYPE_FANATICS && Civs[CivIndex].Government != CIV2_GOVERNMENT_FUNDAMENTALISM )
            {
              Cities[j].Building = CIV2_TYPE_RIFLEMEN;
            }
          }
        }
      }
    }
  }
  if ( (Game.ActiveHumanPlayers & (1 << CivIndex)) != 0 && (int)Government >= CIV2_GOVERNMENT_DESPOTISM && !g_SaveBlock5.Unknown_468 )
  {
    j_Q_ShowTaxRate_sub_40DDC6(CivIndex);
  }
}

//----- (0055C277) --------------------------------------------------------
int __cdecl Q_CanSwitchToGovernment_sub_55C277(int aCiv, int aGovernment)
{
  BOOL vHasStatueOfLiberty; // [esp+10h] [ebp-8h]
  int v4; // [esp+14h] [ebp-4h]

  v4 = 1;
  vHasStatueOfLiberty = j_Q_CivHasWonder_sub_453E51(aCiv, CIV2_WONDER_STATUE_OF_LIBERTY);// Statue of Liberty
  switch ( aGovernment )
  {
    case 2:
      if ( !j_Q_CivHasTech_sub_4BD9F0(aCiv, CIV2_TECH_MONARCHY) && !vHasStatueOfLiberty )// Monarchy
      {
        v4 = 0;
      }
      break;
    case 3:
      if ( !j_Q_CivHasTech_sub_4BD9F0(aCiv, CIV2_TECH_COMMUNISM) && !vHasStatueOfLiberty )// Communism
      {
        v4 = 0;
      }
      break;
    case 4:
      if ( !j_Q_CivHasTech_sub_4BD9F0(aCiv, CIV2_TECH_FUNDAMENTALISM) && !vHasStatueOfLiberty )// Fundamentalism
      {
        v4 = 0;
      }
      if ( !g_RulesCivilizes[0x1F].IsEnabled )
      {
        v4 = 0;
      }
      break;
    case 5:
      if ( !j_Q_CivHasTech_sub_4BD9F0(aCiv, CIV2_TECH_THE_REPUBLIC) && !vHasStatueOfLiberty )// The Republic
      {
        v4 = 0;
      }
      break;
    case 6:
      if ( !j_Q_CivHasTech_sub_4BD9F0(aCiv, CIV2_TECH_DEMOCRACY) && !vHasStatueOfLiberty )// Democracy
      {
        v4 = 0;
      }
      break;
    default:
      return v4;
  }
  return v4;
}

