//----- (0055D685) --------------------------------------------------------
// Processes alliance execution obligations immediately after a containment pact is signed,
// or triggers a cascade forcing an AI to join its partner's ongoing war.
//   AttackerCivIndex The index of the AI deciding whether to declare war (aCiv1).
//   EnemyCivIndex    The index of the mutual enemy target (aCiv2).
//   AllyCivIndex     The index of the pact partner (aCivIndex).
//   Returns 1 if a formal war declaration was triggered, 0 otherwise.
int __cdecl Q_AiExecutePactObligations_sub_55D685(int AttackerCivIndex, int EnemyCivIndex, int AllyCivIndex)
{
  char *text; // eax MAPDST

  if ( (Civs[AttackerCivIndex].Treaties[EnemyCivIndex] & (CIV2_TREATY_WAR|CIV2_TREATY_ALLIANCE)) != 0 )
  {
    return 0;
  }
  // CRITICAL TRIGGER: If our pact partner (AllyCivIndex) is ALREADY at war with the enemy (EnemyCivIndex)
  if ( (Civs[AllyCivIndex].Treaties[EnemyCivIndex] & CIV2_TREATY_WAR) != 0 )
  {
    // Anti-dogpiling protection: If the target enemy is a Human Player, apply diplomatic pacing
    if ( (Game.ActiveHumanPlayers & (1 << EnemyCivIndex)) != 0 )
    {
      // If our AI doesn't have an active Vendetta against the human player
      if ( (Civs[AttackerCivIndex].Treaties[EnemyCivIndex] & CIV2_TREATY_VENDETTA) == 0 )
      {
        // Cooldown safeguard: At least 6 turns must have passed since the last dialogue/contact with the human
        if ( Civs[EnemyCivIndex].LastContactTurn[AttackerCivIndex] - Game.Turn < 6 )
        {
          return 0;
        }
        // Balance safeguard: If the human isn't a dominant hyper-power (Rating < 7), 
        // there is a 66% (2 out of 3) chance the AI chooses to stay out of the war for now.
        if ( Game.CivPowerRating[EnemyCivIndex] < 7u && rand() % 3 )
        {
          return 0;
        }
      }
      Civs[EnemyCivIndex].LastContactTurn[AttackerCivIndex] = Game.Turn;
      Civs[EnemyCivIndex].LastContactTurn[AllyCivIndex] = Game.Turn;
    }
    text = j_Q_GetStringNationPlural_sub_493C7D(AttackerCivIndex);
    j_Q_DlgParams_SetStringText_sub_40FF60(0, text);
    text = j_Q_GetStringNationPlural_sub_493C7D(AllyCivIndex);
    j_Q_DlgParams_SetStringText_sub_40FF60(1, text);
    text = j_Q_GetStringNationPlural_sub_493C7D(EnemyCivIndex);
    j_Q_DlgParams_SetStringText_sub_40FF60(2, text);
    // @title=Diplomats Report
    // The %STRING0 announce they will join the %STRING1
    // in their war against the %STRING2!
    j_Q_PopupSimpleGAMEWithSprite_sub_410030("JOINWAR", &stru_644E48, 0);
    // Symmetrically apply the formal state of War against the target enemy
    j_Q_SetTreaties_sub_467825(AttackerCivIndex, EnemyCivIndex, CIV2_TREATY_WAR);
    return 1;
  }
  else
  {
    // COALITION ALIGNMENT: No active war exists, but both partners share a grudge against the same target
    if ( (Civs[AttackerCivIndex].Treaties[EnemyCivIndex] & CIV2_TREATY_VENDETTA) != 0
      && (Civs[AllyCivIndex].Treaties[EnemyCivIndex] & CIV2_TREATY_VENDETTA) != 0 )
    {
      Civs[AttackerCivIndex].Treaties[EnemyCivIndex] |= CIV2_TREATY__MUTUAL_GRIEVANCE;
      Civs[AllyCivIndex].Treaties[EnemyCivIndex] |= CIV2_TREATY__MUTUAL_GRIEVANCE;
    }
    return 0;
  }
}

