//----- (0055F5A3) --------------------------------------------------------
// AI logic to evaluate available government types and switch to the optimal one.
// Alters government weights dynamically under Human Containment if the AI is lagging behind.
//   CivIndex          Index of the AI civilization.
//   RestrictTechsFlag If true, modifies the ceiling of available governments to evaluate.
void __cdecl Q_AiChooseAndSwitchGovernment_sub_55F5A3(int CivIndex, MACRO_BOOL CapMaxGovernment)
{
  int bestGovernment; // [esp+Ch] [ebp-14h]
  int government; // [esp+10h] [ebp-10h]
  int techDeficit; // [esp+14h] [ebp-Ch]
  int maxWeightFound; // [esp+18h] [ebp-8h]
  int maxGovToEvaluate; // [esp+1Ch] [ebp-4h]

  // Check if political revolution is allowed by scenario rules, or if the civilization is currently in Anarchy
  if ( (Game.MapFlags & CIV2_MAP_FLAG_SCENARIO_STARTED) == 0
    || (ScenarioParameters.Flags & CIV2_SCN_FLAG_NO_GOVT_SWITCH) == 0
    || Civs[CivIndex].Government == CIV2_GOVERNMENT_ANARCHY )
  {
    // By default, AI can evaluate up to the highest progression tier (Democracy)
    maxGovToEvaluate = CIV2_GOVERNMENT_DEMOCRACY;
    if ( CapMaxGovernment )
    {
      // Restrict early-game AI or specific triggers to Republic max
      maxGovToEvaluate = CIV2_GOVERNMENT_REPUBLIC;
      if ( rand() % 3 )
      {
        // ~66% chance to roll back or divert to Fundamentalism instead
        maxGovToEvaluate = CIV2_GOVERNMENT_FUNDAMENTALISM;
      }
    }
    // ANTI-HUMAN COALITION / CONTAINMENT ADJUSTMENTS
    if ( (Game.MapFlags & CIV2_MAP_FLAG_HUMAN_CONTAINMENT) != 0 )
    {
      techDeficit = Civs[Game.CurrentHumanCivIndex].Techs - Civs[CivIndex].Techs;
      // Lagging AI civs are forced to switch from economic growth to total war
      if ( Game.CivPowerRating[CivIndex] < 6u )
      {
        // Heavily penalize representative regimes to prevent AI from picking high-unrest environments during war
        if ( techDeficit > 6 )
        {
          Civs[CivIndex].AiGovernmentWeight[CIV2_GOVERNMENT_DEMOCRACY] = -2;
        }
        if ( techDeficit > 8 )
        {
          Civs[CivIndex].AiGovernmentWeight[CIV2_GOVERNMENT_REPUBLIC] = -1;
        }
      }
    }
    // EARLY GAME FALLBACK RESTRICTIONS
    // If baseline initial/anarchy weight is set as priority
    if ( Civs[CivIndex].AiGovernmentWeight[CIV2_GOVERNMENT_ANARCHY] > 0 )
    {
      maxGovToEvaluate = CIV2_GOVERNMENT_COMMUNISM;
      if ( Civs[CivIndex].Government <= CIV2_GOVERNMENT_REPUBLIC )
      {
        maxGovToEvaluate = CIV2_GOVERNMENT_DESPOTISM;
      }
    }
    // BEST GOVERNMENT SELECTION LOOP
    maxWeightFound = -999;
    bestGovernment = CIV2_GOVERNMENT_DESPOTISM;
    for ( government = 1; maxGovToEvaluate >= government; ++government )
    {
      if ( j_Q_CanSwitchToGovernment_sub_55C277(CivIndex, government) )
      {
        if ( Civs[CivIndex].AiGovernmentWeight[government] >= maxWeightFound )
        {
          maxWeightFound = Civs[CivIndex].AiGovernmentWeight[government];
          bestGovernment = government;
        }
      }
    }
    j_Q_ChangeGovernment_sub_55C69D(CivIndex, bestGovernment);
  }
}

