//----- (00579ED0) --------------------------------------------------------
// Check if can not attack
signed int __cdecl Q_CanNotAttack_sub_579ED0(int CivIndex1, int CivIndex2, int Treaty)
{
  char *text; // eax MAPDST
  int choice; // [esp+Ch] [ebp-4h]

  if ( (Civs[CivIndex1].Treaties[CivIndex2] & CIV2_TREATY_WAR) != 0 )// War
  {
    return 0;
  }
  if ( (Civs[CivIndex1].Treaties[CivIndex2] & Treaty) == 0 )
  {
    return 0;
  }
  if ( (Game.ActivePlayers & (1 << CivIndex2)) == 0 )
  {
    return 0;
  }
  text = j_Q_GetStringNationPlural_sub_493C7D(CivIndex2);
  j_Q_DlgParams_SetStringText_sub_40FF60(1, text);
  if ( (Civs[CivIndex1].Treaties[CivIndex2] & CIV2_TREATY_ALLIANCE) != 0 )
  {
    // @title=Foreign Minister
    // We are currently allied with the %STRING1!
    // Although our units can move through our ally's
    // territory, they cannot enter the same square as our ally's
    // units and cities.  Nor can we have combat with allied
    // units.  Alliances can only be cancelled during diplomatic
    // negotiations.
    j_Q_PopupSimpleGAMEWithSprite_sub_410030(
      "ANNOYALLIED",
      (T_Sprite *)((char *)&stru_648018 + (((char *)&stru_63FC98 - (char *)&stru_648018) & ((Game.TechsDiscovered[CIV2_TECH_COMMUNISM] != 0) - 1))),
      0);
    return 1;
  }
  else
  {
    if ( (Civs[CivIndex1].Treaties[CivIndex2] & CIV2_TREATY_PEACE) != 0 )// Peace
    {
      // @title=Foreign Minister
      // We have signed a peace treaty with the %STRING1!
      // Our reputation will be damaged if we break it!
      choice = j_Q_PopupSimpleGAMEWithSprite_sub_410030("ANNOYPEACE", &stru_6409D8, 0);
    }
    else if ( (Civs[CivIndex1].Treaties[CivIndex2] & CIV2_TREATY_CEASE_FIRE) != 0 )
    {
      if ( (Civs[CivIndex1].Treaties[CivIndex2] & CIV2_TREATY_ACCEPTED_TRIBUTE) != 0 )
      {
        // @title=Foreign Minister
        // We have accepted tribute from the %STRING1!
        // Our reputation will be damaged if we attack them
        // so soon!
        choice = j_Q_PopupSimpleGAMEWithSprite_sub_410030("ANNOYVASSAL", &stru_647388[0x10], 0);
      }
      else
      {
        // @title=Foreign Minister
        // We have signed a cease fire with the %STRING1!
        // Our reputation will be damaged if we break it!
        choice = j_Q_PopupSimpleGAMEWithSprite_sub_410030("ANNOYCEASE", &stru_647388[0x10], 0);
      }
    }
    else
    {
      // @title=Foreign Minister
      // Shall we declare war on the %STRING1?
      choice = j_Q_PopupSimpleGAMEWithSprite_sub_410030("ANNOY", &stru_644E48, 0);
    }
    if ( choice == 1 )
    {
      if ( j_Q_IsOverruledBySenate_sub_55BEF9(CivIndex1, CivIndex2) )
      {
        // @title=Foreign Minister
        // You are overruled by the Senate!  Action cancelled.
        j_Q_PopupSimpleGAMEWithSprite_sub_410030("OVERRULE", &stru_646878[Civs[CivIndex1].Government], 0);
        return 1;
      }
      else
      {
        if ( Civs[CivIndex1].Government >= CIV2_GOVERNMENT_REPUBLIC )
        {
          if ( j_Q_CivHasWonder_sub_453E51(CivIndex2, CIV2_WONDER_UNITED_NATIONS) )// United Nations
          {
            // @title=Defense Minister
            // The Senate chooses to allow the action
            // under the guise of a U.N. "peacekeeping" mission.
            j_Q_PopupSimpleGAMEWithSprite_sub_410030("ALLOWUN", &stru_646878[Civs[CivIndex1].Government], 0);
          }
          else if ( (Civs[CivIndex2].Treaties[CivIndex1] & CIV2_TREATY_0x1000) != 0 || Civs[CivIndex2].Reputation )
          {
            text = j_Q_GetNationAdjectiveText_sub_410070(CivIndex2);
            j_Q_DlgParams_SetStringText_sub_40FF60(0, text);
            // @title=Defense Minister
            // Previous %STRING0 aggression against us
            // convinces the Senate to allow this action.
            j_Q_PopupSimpleGAMEWithSprite_sub_410030("ALLOWAGGRESSOR", &stru_646878[Civs[CivIndex1].Government], 0);
          }
          else
          {
            // @title=Defense Minister
            // Hawk Party derails attempted Senate interference.
            // Action confirmed!
            j_Q_PopupSimpleGAMEWithSprite_sub_410030("ALLOWHAWKS", &stru_646878[Civs[CivIndex1].Government], 0);
          }
        }
        return 0;
      }
    }
    else
    {
      return 1;
    }
  }
}

