//----- (005DE780) --------------------------------------------------------
// Initializes the game palette based on hardware capabilities and system colors.
void __cdecl Q_InitPalette_sub_5DE780(P_Palette palette)
{
  LPBYTE ptr; // [esp+10h] [ebp-Ch] MAPDST
  int i; // [esp+14h] [ebp-8h]
  int j; // [esp+14h] [ebp-8h]
  int k; // [esp+14h] [ebp-8h]
  HDC hdc; // [esp+18h] [ebp-4h]

  // Windows 3.0+ palette version
  palette->palVersion = 0x300;
  palette->palNumEntries = 256;
  // Get Device Context for the primary monitor
  hdc = GetDC(0);
  // Check if the device supports a palette (e.g., 8-bit/256 color mode)
  if ( (GetDeviceCaps(hdc, RASTERCAPS) & RC_PALETTE) != 0 )
  {
    // Usually results in 10 (20 system colors total, 10 at each end)
    g_SystemPalettePadding = GetDeviceCaps(hdc, NUMCOLORS) / 2;
    GetSystemPaletteEntries(hdc, 0, 256u, palette->Colors);
  }
  else
  {
    // No hardware palette support (16-bit, 24-bit, 32-bit color modes)
    g_SystemPalettePadding = 0;
    g_IsPaletteBasedDevice = FALSE;
  }
  for ( i = 0; i < g_SystemPalettePadding; ++i )
  {
    palette->Colors[i].peFlags = 0;
  }
  while ( 256 - g_SystemPalettePadding > i )
  {
    palette->Colors[i].peRed = 0;
    palette->Colors[i].peGreen = 0;
    palette->Colors[i].peBlue = 0;
    palette->Colors[i++].peFlags = PC_NOCOLLAPSE;
  }
  while ( i < 256 )
  {
    palette->Colors[i++].peFlags = 0;
  }
  // If the device is NOT palette-based, use a hardcoded set of "fixed" colors
  if ( g_IsPaletteBasedDevice == FALSE )
  {
    ptr = (LPBYTE)g_DefaultSystemRGBTable;
    // Fill the first 10 entries with fixed system colors
    for ( j = 0; j < 10; ++j )
    {
      palette->Colors[j].peRed = *ptr++;
      palette->Colors[j].peGreen = *ptr;
      palette->Colors[j].peBlue = ptr[1];
      ptr += 2;
    }
    // Fill the last 10 entries with fixed system colors
    for ( k = 246; k < 256; ++k )
    {
      palette->Colors[k].peRed = *ptr++;
      palette->Colors[k].peGreen = *ptr;
      palette->Colors[k].peBlue = ptr[1];
      ptr += 2;
    }
  }
  ReleaseDC(0, hdc);
}
